/// @title Vault token for staked stToken
/// @notice Is a vault that takes stToken and gives you wstToken erc20 tokens
/** @dev Exchange rate between stToken and wstToken floats, you can convert your wstToken for more stToken over time.
    Exchange rate increases as the frax msig mints new stToken corresponding to the staking yield and drops it into the vault (wstToken contract).
    There is a short time period, “cycles” which the exchange rate increases linearly over. This is to prevent gaming the exchange rate (MEV).
    The cycles are constant length, but calling syncRewards slightly into a would-be cycle keeps the same would-be endpoint (so cycle ends are every X seconds).
    Someone must call syncRewards, which queues any new stToken in the contract to be added to the redeemable amount.
    wstToken adheres to ERC-4626 vault specs 
    Mint vs Deposit
    mint() - deposit targeting a specific number of wstToken out
    deposit() - deposit knowing a specific number of stToken in */
contract wstACME is xERC4626, ReentrancyGuard {

    /* ========== CONSTRUCTOR ========== */
    constructor(ERC20 _underlying, uint32 _rewardsCycleLength)
        ERC4626(_underlying, "Wrapped Staked ACME", "wstACME")
        xERC4626(_rewardsCycleLength)
    {}

    /// @notice inlines syncRewards with deposits when able
    function deposit(uint256 assets, address receiver) public override returns (uint256 shares) {
        return super.deposit(assets, receiver);
    }
    
    /// @notice inlines syncRewards with mints when able
    function mint(uint256 shares, address receiver) public override returns (uint256 assets) {
        return super.mint(shares, receiver);
    }

    /// @notice inlines syncRewards with withdrawals when able
    function withdraw(
        uint256 assets,
        address receiver,
        address owner
    ) public override returns (uint256 shares) {
        return super.withdraw(assets, receiver, owner);
    }

    /// @notice inlines syncRewards with redemptions when able
    function redeem(
        uint256 shares,
        address receiver,
        address owner
    ) public override returns (uint256 assets) {
        return super.redeem(shares, receiver, owner);
    }

    /// @notice How much stToken is 1E18 wstToken worth. Price is in stToken, not USD
    function pricePerShare() public view returns (uint256) {
        return convertToAssets(1e18);
    }

    /// @notice Approve and deposit() in one transaction
    function depositWithSignature(
        uint256 assets,
        address receiver,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external nonReentrant returns (uint256 shares) {
        uint256 amount = approveMax ? type(uint256).max : assets;
        asset.permit(msg.sender, address(this), amount, deadline, v, r, s);
